package com.dreamspex.admin;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="banners")
public class Banner { @Id @Column(length=255) private String id=UUID.randomUUID().toString(); @Column(nullable=false) private String title; @Column(name="image_url",nullable=false) private String imageUrl; @Column(name="mobile_image_url") private String mobileImageUrl; @Column(name="desktop_storage_key") private String desktopStorageKey; @Column(name="mobile_storage_key") private String mobileStorageKey; @Column(name="desktop_media_type",nullable=false) private String desktopMediaType="IMAGE"; @Column(name="desktop_video_url") private String desktopVideoUrl; @Column(name="desktop_video_storage_key") private String desktopVideoStorageKey; private String subtitle; @Column(columnDefinition="TEXT") private String description; @Column(name="button_text") private String buttonText; @Column(name="secondary_button_text") private String secondaryButtonText; @Column(name="positioning") private String positioning; @Column(name="link_url") private String linkUrl; @Column(name="secondary_link_url") private String secondaryLinkUrl; @Column(name="sort_order",nullable=false) private int sortOrder; @Column(nullable=false) private String status="DRAFT"; @Column(name="starts_at") private Instant startsAt; @Column(name="ends_at") private Instant endsAt; @Column(name="created_at",nullable=false) private Instant createdAt=Instant.now(); @Column(name="updated_at",nullable=false) private Instant updatedAt=Instant.now(); public String getId(){return id;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getImageUrl(){return imageUrl;} public void setImageUrl(String v){imageUrl=v;} public String getMobileImageUrl(){return mobileImageUrl;} public void setMobileImageUrl(String v){mobileImageUrl=v;} public String getDesktopStorageKey(){return desktopStorageKey;} public void setDesktopStorageKey(String v){desktopStorageKey=v;} public String getMobileStorageKey(){return mobileStorageKey;} public void setMobileStorageKey(String v){mobileStorageKey=v;} public String getDesktopMediaType(){return desktopMediaType;} public void setDesktopMediaType(String v){desktopMediaType=v;} public String getDesktopVideoUrl(){return desktopVideoUrl;} public void setDesktopVideoUrl(String v){desktopVideoUrl=v;} public String getDesktopVideoStorageKey(){return desktopVideoStorageKey;} public void setDesktopVideoStorageKey(String v){desktopVideoStorageKey=v;} public String getSubtitle(){return subtitle;} public void setSubtitle(String v){subtitle=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public String getButtonText(){return buttonText;} public void setButtonText(String v){buttonText=v;} public String getSecondaryButtonText(){return secondaryButtonText;} public void setSecondaryButtonText(String v){secondaryButtonText=v;} public String getPositioning(){return positioning;} public void setPositioning(String v){positioning=v;} public String getLinkUrl(){return linkUrl;} public void setLinkUrl(String v){linkUrl=v;} public String getSecondaryLinkUrl(){return secondaryLinkUrl;} public void setSecondaryLinkUrl(String v){secondaryLinkUrl=v;} public int getSortOrder(){return sortOrder;} public void setSortOrder(int v){sortOrder=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public Instant getStartsAt(){return startsAt;} public void setStartsAt(Instant v){startsAt=v;} public Instant getEndsAt(){return endsAt;} public void setEndsAt(Instant v){endsAt=v;} }
